declare const STARTER_QUALITY_POLICY = "# ==============================================================================\n# AI-SDLC: Software Quality, Coding Rules & Release Gate Policy\n# ==============================================================================\nversion: \"1.0\"\nproject: \"Standard AI-SDLC Project\"\nenforcement_mode: \"STRICT\"\n\nscope:\n  target_directories:\n    - \"src\"\n    - \"lib\"\n    - \"examples\"\n    - \"tests\"\n  supported_extensions:\n    - \".ts\"\n    - \".js\"\n    - \".py\"\n    - \".java\"\n    - \".go\"\n    - \".cs\"\n    - \".rs\"\n    - \".cpp\"\n    - \".c\"\n  exclude_patterns:\n    - \"node_modules\"\n    - \"__pycache__\"\n    - \".pytest_cache\"\n    - \"target\"\n    - \"bin\"\n    - \"obj\"\n    - \".git\"\n    - \"reports\"\n    - \"dist\"\n    - \".changeset\"\n\nthresholds:\n  cyclomatic_complexity:\n    max_per_function: 10\n  cognitive_complexity:\n    max_per_function: 15\n  maintainability_index:\n    min_acceptable_score: 50.0\n  function_length:\n    max_function_lines: 40\n";
declare const STARTER_LICENSE_POLICY = "# ==============================================================================\n# AI-SDLC: Open Source License Compliance & Governance Policy\n# ==============================================================================\nversion: \"1.0\"\nproject: \"Standard AI-SDLC Project\"\ndefault_action: \"DENY\"\n\ncategories:\n  permissive_free:\n    action: \"ALLOW\"\n    description: \"Permissive commercial use licenses. Attribution only required.\"\n    spdx_identifiers:\n      - \"MIT\"\n      - \"Apache-2.0\"\n      - \"BSD-2-Clause\"\n      - \"BSD-3-Clause\"\n      - \"ISC\"\n      - \"Unlicense\"\n      - \"CC0-1.0\"\n      - \"0BSD\"\n\n  weak_copyleft_conditional:\n    action: \"REVIEW_REQUIRED\"\n    description: \"Allowed only as dynamically linked decoupled libraries.\"\n    spdx_identifiers:\n      - \"LGPL-2.1-only\"\n      - \"LGPL-3.0-only\"\n      - \"MPL-2.0\"\n\n  strong_copyleft_viral:\n    action: \"DENY\"\n    description: \"Forbidden due to viral copyleft forcing source code disclosure.\"\n    spdx_identifiers:\n      - \"GPL-2.0-only\"\n      - \"GPL-3.0-only\"\n      - \"AGPL-3.0-only\"\n      - \"AGPL-3.0-or-later\"\n\n  commercial_acquisition_required:\n    action: \"COMMERCIAL_APPROVAL_REQUIRED\"\n    description: \"Source-available code requiring commercial license for SaaS deployment.\"\n    spdx_identifiers:\n      - \"SSPL-1.0\"\n      - \"BSL-1.1\"\n";
